import {createHost,migrateLegacy,calendar,associateBlockerTask} from './host.mjs?v=4.1-recent-five';
import {totals,timerView} from './core/session.mjs';
import {createTask,editTask,upsertBlocker,editBlocker} from './core/entities.mjs';
import {focusMarkup,recordsModel} from './view.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=ms=>{const s=Math.floor(ms/1000);return `${Math.floor(s/3600)?Math.floor(s/3600)+':':''}${String(Math.floor(s/60)%60).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;};
const status={Ready:'准备开始',Focusing:'专注中',Paused:'已暂停',Resting:'休息中',Ended:'已结束'};
const runtime_id=crypto.randomUUID();let tab_id=sessionStorage.getItem('gmf-mf-tab');if(!tab_id){tab_id=crypto.randomUUID();sessionStorage.setItem('gmf-mf-tab',tab_id);}
let setup={mode:'free',focus_min:25,rest_min:5,task_id:null},showSetup=false;let guide=true;try{guide=localStorage.getItem('gmf-mf-guide-seen')!=='1';}catch{}
let api,hook={},page='focus',lastSignature='',busy=false,seenNotices=new Set();
const stamp=()=>({wall_ms:Date.now(),mono_ms:performance.now(),runtime_id});
const channel=typeof BroadcastChannel!=='undefined'?new BroadcastChannel('gmf-mf-v3'):null;
function say(message){const el=document.querySelector('[data-mf-status]');if(el)el.textContent=message;else hook.toast?.(message);}
async function act(fn,{redraw=true}={}){if(busy)return;busy=true;try{await fn();channel?.postMessage('changed');if(redraw)mount();paint();}catch(e){console.error(e);say('未保存：'+e.message);}finally{busy=false;}}
function allSessions(){return [...api.row.history,...(api.row.current?[api.row.current]:[])];}
function visibleSessions(){return allSessions().filter(s=>!api.row.hidden_ids.includes(s.session_id));}
function context(){const c=hook.context?.();return {...(c?.topic_id?c:api.row.current?.context||c||{}),source:'MF'};}
function controls(s){if(!s||s.state==='Ended')return '<button class="btn accent" data-mf="start">开始专注</button>';return `${s.state==='Focusing'?'<button class="btn secondary" data-mf="pause">暂停</button><button class="btn secondary" data-mf="rest">休息</button>':''}${['Paused','Resting'].includes(s.state)?'<button class="btn accent" data-mf="resume">继续专注</button>':''}<button class="ghost-btn" data-mf="end">结束会话</button>`;}
function focus(){const ctx=api.row.current?.state!=='Ended'&&api.row.current?.context||context();return focusMarkup({session:api.row.current,tasks:api.row.tasks,archived:api.row.archived_task_ids,setup,showSetup,context:ctx,guide,reviewURL:ctx.topic_id?GMFShared.url('review',ctx):null});}
function blockerForm(){return '<form id="mf-blocker-form" class="mf-inline"><input class="mf-quick" name="title" aria-label="问题内容" placeholder="一句话留下暂时不懂的地方" required maxlength="4000"><button class="btn secondary">记录问题</button></form>';}
function tasks(){const items=api.row.tasks.filter(t=>!(api.row.archived_task_ids||[]).includes(t.task_id));function row(t){return `<div class="mf-row ${t.completed?'is-complete':''} ${t.parent_id?'mf-child':''}"><details class="mf-row-title"><summary><b data-user-content class="${t.completed?'done':''}">${t.important?'★ ':''}${esc(t.title)}</b></summary></details>${t.estimated_ms?`<span class="tiny"> · 预计 ${t.estimated_ms/60000} 分钟</span>`:''}<div class="mf-inline"><button class="btn secondary small" data-task-done="${esc(t.task_id)}">${t.completed?'重新打开':'标记完成'}</button><button class="ghost-btn" data-task-use="${esc(t.task_id)}">继续此任务</button><details class="action-menu"><summary>更多操作</summary><div><button class="ghost-btn" data-task-edit="${esc(t.task_id)}">编辑</button>${!t.parent_id?`<button class="ghost-btn" data-task-child="${esc(t.task_id)}">添加子任务</button>`:''}<button class="ghost-btn danger" data-task-delete="${esc(t.task_id)}">删除任务</button></div></details></div></div>`;}
return `<h1>任务</h1><p class="muted">只写任务名称，就能开始。</p><form id="mf-task-form" class="mf-inline"><input class="mf-quick" name="title" aria-label="任务名称" placeholder="下一件要做的小事" required maxlength="4000"><button class="btn accent">添加任务</button></form><section class="card pad section"><h2>未完成</h2>${items.filter(t=>!t.completed&&!t.parent_id).map(t=>row(t)+items.filter(c=>c.parent_id===t.task_id&&!c.completed).map(row).join('')).join('')}${items.filter(t=>!t.completed&&t.parent_id&&items.find(p=>p.task_id===t.parent_id)?.completed).map(row).join('')}${!items.some(t=>!t.completed)?'<p class="muted">没有未完成任务。</p>':''}</section><section class="card pad section"><h2>已完成</h2>${items.filter(t=>t.completed).map(row).join('')||'<p class="muted">完成的任务会留在这里。</p>'}</section>${archived("task")}`;}
function blockers(){return `<h1>问题</h1><p class="muted">先留下，准备好再回来。</p>${blockerForm()}${[false,true].map(resolved=>`<section class="card pad section"><h2>${resolved?'已解决':'未解决'}</h2>${api.row.blockers.filter(b=>b.resolved===resolved&&!(api.row.archived_blocker_ids||[]).includes(b.blocker_id)).map(b=>`<div class="mf-row"><b data-user-content>${esc(b.title)}</b>${b.notes?`<p data-user-content>${esc(b.notes)}</p>`:''}<p class="tiny">${b.context.topic_id?'Topic '+esc(b.context.topic_id):'未关联 Topic'}${b.question_ref?' · 模考 '+esc(b.question_ref.question_id):''}</p><div class="mf-inline"><button class="btn secondary small" data-blocker-toggle="${esc(b.blocker_id)}">${resolved?'重新打开':'标记解决'}</button><button class="ghost-btn blocker-secondary" data-blocker-edit="${esc(b.blocker_id)}">补充笔记</button><button class="ghost-btn blocker-secondary" data-blocker-delete="${esc(b.blocker_id)}">删除问题</button>${b.context.topic_id?`<button class="ghost-btn" data-blocker-topic="${esc(b.blocker_id)}">打开关联教材</button>`:''}${b.question_ref?`<a class="ghost-btn" href="${esc(GMFShared.safeReturn(b.context.return_to))}">返回模考原题</a>`:''}</div></div>`).join('')||'<p class="muted">暂无问题。</p>'}</section>`).join('')}${archived("blocker")}`;}
function archived(kind){const task=kind==='task',items=(task?api.row.tasks:api.row.blockers).filter(x=>(api.row[task?'archived_task_ids':'archived_blocker_ids']||[]).includes(x[task?'task_id':'blocker_id']));return items.length?`<details class="section"><summary>${task?'已删除任务':'已删除问题'} (${items.length})</summary><p class="tiny">可随时恢复，已有学习记录保留。</p>${items.map(x=>`<div class="mf-row"><span data-user-content>${esc(x.title)}</span><button class="ghost-btn" data-${kind}-restore="${esc(x[task?'task_id':'blocker_id'])}">恢复</button></div>`).join('')}</details>`:'';}
function records(){const today=new Date(),keys=Array.from({length:7},(_,i)=>calendar.dayKey(+new Date(today.getFullYear(),today.getMonth(),today.getDate()-6+i))),model=recordsModel(api.row,keys,calendar),sum=model.summary,monday=new Date(today.getFullYear(),today.getMonth(),today.getDate()-(today.getDay()+6)%7),week=keys.filter(k=>k>=calendar.dayKey(+monday)).reduce((n,k)=>n+sum.days[k].focus_ms,0),max=Math.max(60000,...keys.map(k=>sum.days[k].focus_ms));
return `<h1>记录</h1><p class="muted">专注状态时间，不等于经过验证的有效学习时间。</p><div class="grid cols-2"><section class="card metric"><div class="label">本周专注</div><div class="value">${fmt(week)}</div></section><section class="card metric"><div class="label">累计专注</div><div class="value">${fmt(sum.focus_ms)}</div><p class="tiny">累计休息 ${fmt(sum.rest_ms)}</p></section></div><section class="card pad section"><h2>最近七天</h2><div class="mf-chart">${keys.map(k=>`<div><div class="bar-track"><div class="bar" style="height:${sum.days[k].focus_ms/max*100}%"></div></div><small>${k.slice(5)}</small><span>${Math.round(sum.days[k].focus_ms/60000)} 分</span></div>`).join('')}</div></section><section class="card pad section"><h2>学习会话</h2><p class="tiny">仅显示最近 5 次，最新的排在最上面。</p>${model.visible.map(s=>{const t=totals(s);return `<details class="mf-row"><summary>${new Date(s.created_at).toLocaleString()} · ${status[s.state]} · 专注 ${fmt(t.focus_ms)}</summary><p>休息 ${fmt(t.rest_ms)} · ${s.context.topic_id?'Topic '+esc(s.context.topic_id):'自由学习'}</p><p>任务：${Object.entries(t.tasks).map(([id,ms])=>esc(api.row.tasks.find(t=>t.task_id===id)?.title||id)+' '+fmt(ms)).join('、')||'未关联'}</p><p>问题：${api.row.blockers.filter(b=>b.session_ids.includes(s.session_id)).map(b=>esc(b.title)).join('、')||'无'}</p></details>`;}).join('')||'<p class="muted">开始一次专注，记录会保存在这里。</p>'}</section><section class="card pad section"><h2>数据与旧记录</h2><div class="mf-inline"><button class="btn secondary" data-mf="export">导出完整备份</button><label class="ghost-btn">导入完整备份<input id="mf-import-backup" type="file" accept="application/json" hidden></label><button class="ghost-btn" data-mf="hide-history">隐藏心流历史列表</button><button class="ghost-btn" data-mf="restore-history">恢复历史列表</button></div><p class="tiny">隐藏列表不影响累计时间、七日统计和共享学习证据。</p><p class="tiny">旧版记录已保留在完整备份中。</p></section>`;}
export async function init(options){hook=options;await migrateLegacy(LearningStore);api=createHost(LearningStore,{runtime_id,tab_id,stamp,onChange:()=>paint()});await api.refresh();seenNotices=new Set(api.row.current?.notices.map(n=>n.id)||[]);let handoff;try{handoff=JSON.parse(sessionStorage.getItem('gmf-mf-handoff')||'null');sessionStorage.removeItem('gmf-mf-handoff');}catch{}await api.recover(true);if(handoff&&Date.now()-handoff.at<6000&&api.row.current?.session_id===handoff.id&&!api.row.exam_ids.length&&api.row.current.state==='Paused')await api.command('resume');channel&&(channel.onmessage=()=>api.refresh().catch(e=>say(e.message)));
setInterval(()=>{if(!document.hidden&&!busy)api.heartbeat().then(()=>{channel?.postMessage('changed');paint();}).catch(e=>say('计时保存失败，请暂停并导出备份：'+e.message));},1000);
const suspend=()=>{if(api.row.current?.anchor?.runtime_id===runtime_id)api.command('suspend').then(()=>channel?.postMessage('changed')).catch(console.error);};document.addEventListener('visibilitychange',()=>{if(document.hidden)suspend();else api.refresh().then(()=>api.recover()).catch(console.error);});addEventListener('pagehide',suspend);addEventListener('pageshow',e=>{if(e.persisted)api.refresh().then(()=>api.recover(true));});document.addEventListener('keydown',e=>{if(e.key==='Escape')document.body.classList.remove('mf-immersed');});return api;}
export function template(){return '<div id="mf-v3-root" class="mf-v3"></div>';}
export function mount(selected){if(selected)page=['focus','tasks','blockers','records'].includes(selected)?selected:'focus';if(page!=='focus')document.body.classList.remove('mf-immersed');const el=document.getElementById('mf-v3-root');if(!el)return;const ctx=context(),back=GMFShared.safeReturn(ctx.return_to);el.innerHTML=`${ctx.return_to?`<p class="mf-entry"><a class="ghost-btn" href="${esc(back)}">${new URL(back).pathname.includes('/assessment/')?'返回模考 / 练习':'返回学习路径'}${ctx.topic_id?' · Topic '+esc(ctx.topic_id):''}</a></p>`:''}<nav class="mf-v3-nav" aria-label="心流页面">${[['focus','专注'],['tasks','任务'],['blockers','问题'],['records','记录']].map(([id,title])=>`<a class="ghost-btn" href="#mindflow/${id}" ${page===id?'aria-current="page"':''}>${title}</a>`).join('')}</nav><p data-mf-status role="status"></p>${({focus,tasks,blockers,records}[page])()}`;GMFShared.localize?.(el);bind(el);paint();}
function dialog(title,body,onSubmit){document.getElementById('mf-editor')?.remove();const d=document.createElement('dialog');d.id='mf-editor';d.className='card pad mf-v3';d.setAttribute('aria-label',title);d.innerHTML=`<form><h2>${esc(title)}</h2>${body}<p data-error role="alert"></p><div class="mf-inline"><button class="btn accent">保存</button><button type="button" class="ghost-btn" data-cancel>取消</button></div></form>`;document.body.append(d);d.querySelector('[data-cancel]').onclick=()=>d.close();d.querySelector('form').onsubmit=async e=>{e.preventDefault();const submit=d.querySelector('button');if(submit.disabled)return;submit.disabled=true;try{await onSubmit(new FormData(e.target));d.close();mount();channel?.postMessage('changed');say('已保存。');}catch(err){d.querySelector('[data-error]').textContent='未保存。'+err.message+' 请重试。';}finally{submit.disabled=false;}};d.showModal();}
function bind(el){const mode=el.querySelector('#mf-mode');if(mode)mode.onchange=()=>{setup.mode=mode.value;el.querySelector('[data-timed-settings]').hidden=mode.value==='free';paint();};for(const id of ['focus','rest']){const field=el.querySelector('#mf-'+id+'-min');if(field)field.oninput=()=>{setup[id+'_min']=field.value;paint();};}el.querySelector('#mf-import-backup')?.addEventListener('change',e=>act(async()=>{const f=e.target.files[0];if(!f)return;const result=await LearningStore.restoreBackup(JSON.parse(await f.text()));await api.refresh();await api.recover(true);say(`已导入 ${result.inserted} 条，保留现有 ${result.kept} 条；冲突原文已归档。刷新页面读取其他模块。`);},{redraw:false}));el.querySelectorAll('[data-mf]').forEach(b=>b.onclick=()=>act(async()=>{const cmd=b.dataset.mf;if(cmd==='new-session'){showSetup=true;setup.task_id=null;return;}if(cmd==='dismiss-guide'){guide=false;try{localStorage.setItem('gmf-mf-guide-seen','1');}catch{}return;}if(cmd==='blocker'){dialog('记录问题','<label>问题内容<textarea name="title" aria-label="问题内容" required maxlength="4000"></textarea></label>',f=>addBlocker(f.get('title'),api.row.current?.context||context()));return;}if(cmd==='help'){dialog('使用帮助','<p>无需任务也能开始。自由计时向上累计；定时模式倒数，到时提醒，不自动结束。</p><p>暂停和休息不计入专注。切到后台、刷新或重新打开时安全暂停，回来后点击继续。</p><p>任务、问题与完整备份在对应页面。回忆与修正可从关联 Topic 打开。</p>',async()=>{});return;}if(cmd==='start'){showSetup=false;return api.start({mode:document.getElementById('mf-mode')?.value||'free',focus_ms:Number(document.getElementById('mf-focus-min')?.value||25)*60000,rest_ms:Number(document.getElementById('mf-rest-min')?.value||5)*60000,context:context(),task_id:document.getElementById('mf-current-task')?.value||null});}if(['pause','rest','resume','end'].includes(cmd))return api.command(cmd);if(cmd==='immerse'||cmd==='exit'){document.body.classList.toggle('mf-immersed',cmd==='immerse');return;}if(cmd==='export'){const data=await LearningStore.exportAll(),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download='GiveMeFive-backup-'+calendar.dayKey(Date.now())+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);return;}if(cmd==='hide-history'){if(confirm('归档已结束的 心流历史列表？任务、问题和学习记录保留。')&&confirm('确认归档？之后可用“恢复历史列表”撤销。'))await api.mutate(r=>{r.hidden_ids=[...new Set([...r.hidden_ids,...allSessions().filter(s=>s.state==='Ended').map(s=>s.session_id)])];return r;});return;}if(cmd==='restore-history')return api.mutate(r=>{r.hidden_ids=[];return r;});}));
el.querySelector('#mf-current-task')?.addEventListener('change',e=>{setup.task_id=e.target.value||null;if(api.row.current&&api.row.current.state!=='Ended')act(()=>api.command('switch_task',{task_id:e.target.value||null}));});
el.querySelector('#mf-task-form')?.addEventListener('submit',e=>{e.preventDefault();const title=new FormData(e.target).get('title');act(()=>api.mutate(r=>{r.tasks.push(createTask({task_id:crypto.randomUUID(),title,context:context()},r.tasks));return r;}));});
el.querySelector('#mf-blocker-form')?.addEventListener('submit',e=>{e.preventDefault();const title=new FormData(e.target).get('title');act(()=>addBlocker(title,context()));});
for(const b of el.querySelectorAll('[data-task-done]'))b.onclick=()=>act(()=>api.mutate(r=>{r.tasks=r.tasks.map(t=>t.task_id===b.dataset.taskDone?editTask(t,{completed:!t.completed}):t);return r;}));
for(const b of el.querySelectorAll('[data-task-use]'))b.onclick=()=>act(async()=>{const id=b.dataset.taskUse;if(!api.row.current||api.row.current.state==='Ended')await api.start({task_id:id,context:context()});else await api.command('switch_task',{task_id:id});location.hash='mindflow/focus';});
for(const b of el.querySelectorAll('[data-task-edit],[data-task-child]'))b.onclick=()=>{const t=api.row.tasks.find(t=>t.task_id===(b.dataset.taskEdit||b.dataset.taskChild)),child=!!b.dataset.taskChild;dialog(child?'添加一级子任务':'编辑任务',`<label>名称 <input name="title" required value="${esc(child?'':t.title)}"></label><p><label><input name="important" type="checkbox" ${!child&&t.important?'checked':''}> 重要</label></p><p><label>预计分钟（可选） <input name="estimate" type="number" min="1" max="100000" value="${!child&&t.estimated_ms?t.estimated_ms/60000:''}"></label></p>`,f=>api.mutate(r=>{const patch={title:f.get('title'),important:f.has('important'),estimated_ms:f.get('estimate')?Number(f.get('estimate'))*60000:null};if(child)r.tasks.push(createTask({task_id:crypto.randomUUID(),parent_id:t.task_id,...patch},r.tasks));else r.tasks=r.tasks.map(x=>x.task_id===t.task_id?editTask(x,patch):x);return r;}));};
for(const kind of ['task','blocker'])for(const action of ['delete','restore'])for(const b of el.querySelectorAll(`[data-${kind}-${action}]`))b.onclick=()=>act(()=>api.mutate(r=>{const id=b.getAttribute(`data-${kind}-${action}`),field=kind==='task'?'archived_task_ids':'archived_blocker_ids',ids=kind==='task'?[id,...r.tasks.filter(t=>t.parent_id===id).map(t=>t.task_id)]:[id];r[field]=action==='delete'?[...new Set([...(r[field]||[]),...ids])]:(r[field]||[]).filter(x=>!ids.includes(x));return r;}));
for(const b of el.querySelectorAll('[data-blocker-toggle]'))b.onclick=()=>act(()=>api.mutate(r=>{r.blockers=r.blockers.map(x=>x.blocker_id===b.dataset.blockerToggle?editBlocker(x,{resolved:!x.resolved}):x);return r;}));
for(const b of el.querySelectorAll('[data-blocker-edit]'))b.onclick=()=>{const old=api.row.blockers.find(x=>x.blocker_id===b.dataset.blockerEdit);dialog('补充问题笔记',`<label>问题 <input name="title" required value="${esc(old.title)}"></label><p><label>笔记 <textarea name="notes">${esc(old.notes)}</textarea></label></p>`,f=>api.mutate(r=>{r.blockers=r.blockers.map(x=>x.blocker_id===old.blocker_id?editBlocker(x,{title:f.get('title'),notes:f.get('notes')}):x);return r;}));};
for(const b of el.querySelectorAll('[data-blocker-topic]'))b.onclick=()=>{const x=api.row.blockers.find(x=>x.blocker_id===b.dataset.blockerTopic);hook.openTopic(x.context);};
}
export async function addBlocker(title,ctx,question_ref=null){return api.mutate(r=>{const result=upsertBlocker(r.blockers,{blocker_id:crypto.randomUUID(),title,context:ctx,question_ref,session_id:r.current?.state!=='Ended'?r.current?.session_id:null});result.blocker=associateBlockerTask(result.blocker,r.current?.state!=='Ended'?r.current?.task_id:null);const i=r.blockers.findIndex(x=>x.blocker_id===result.blocker.blocker_id);if(i>=0)r.blockers[i]=result.blocker;else r.blockers.push(result.blocker);return r;});}
export function miniTemplate(){return '<div id="mf-mini" class="mf-mini" hidden></div>';}
function paint(){if(!api)return;const s=api.row.current,v=s?timerView(s):null,mini=document.getElementById('mf-mini');if(mini){mini.hidden=!!document.querySelector('.mf-focus-panel')||!!api.row.exam_ids.length||!s||s.state==='Ended';const signature=s?.state+':'+s?.session_id;if(mini.dataset.signature!==signature){mini.dataset.signature=signature;mini.innerHTML=s?`<a href="#mindflow/focus">心流 · <span data-mini-state>${status[s.state]}</span> <b data-mini-clock></b></a>${controls(s)}`:'';bind(mini);}const c=mini.querySelector('[data-mini-clock]');if(c)c.textContent=fmt(v?.focus_ms||0);}
const ready=(!s||s.state==='Ended'&&showSetup);const clock=document.querySelector('[data-mf-clock]');if(clock)clock.textContent=fmt(ready?(setup.mode==='pomodoro'?Math.max(0,Number(setup.focus_min)||0)*60000:0):v?(s.state==='Ended'||v.remaining_ms===null?v.focus_ms:v.overtime_ms>0?v.overtime_ms:v.remaining_ms):0);const st=document.querySelector('[data-mf-state]');if(st)st.textContent=(ready?'准备开始':status[s?.state]||'准备开始')+(!ready&&v?.overtime_ms>0?' · 已超时，继续累计':'');const ring=document.querySelector('[data-ring]');if(ring){ring.parentElement.style.display=ready||s?.state==='Ended'||v?.progress==null?'none':'';ring.style.strokeDashoffset=String(301.593*(1-(v?.progress||0)));}const total=document.querySelector('[data-mf-totals]');if(total)total.textContent=!ready&&s?.state!=='Ended'?`本次专注 ${fmt(v?.focus_ms||0)} · 休息 ${fmt(v?.rest_ms||0)}`:'';const caption=document.querySelector('[data-mode-caption]');if(caption&&ready)caption.textContent=setup.mode==='free'?'自由计时 · 正计时':'定时模式 · 倒计时';
for(const n of s?.notices||[])if(api.row.exam_ids.length){seenNotices.add(n.id);}else if(!seenNotices.has(n.id)){seenNotices.add(n.id);say(n.kind==='rest'?'休息时间到了，可以继续休息或主动开始专注。':'本轮专注时间到了，可以继续或休息。');}const notice=document.querySelector('[data-mf-notice]');if(notice)notice.textContent=s?.state==='Paused'&&(s?.pause_reason==='recovered'||s?.pause_reason==='unconfirmed_gap')?'已安全暂停；未确认的离线时间未计入。':'';
const sig=s?.session_id+':'+s?.state+':'+s?.task_id+':'+JSON.stringify([api.row.tasks,api.row.blockers]);if(lastSignature&&sig!==lastSignature&&document.getElementById('mf-v3-root')&&!busy){lastSignature=sig;mount();}lastSignature=sig;
}
export function attachPL(ctx){const box=document.getElementById('mf-pl');if(!box)return;box.innerHTML='<div class="mf-inline"><a class="btn secondary" href="'+esc(GMFShared.url('assessment',ctx))+'">练习本知识点</a><button class="btn secondary" id="pl-start-focus">开始专注</button><a class="ghost-btn" href="#mindflow/blockers">问题记录</a><form id="pl-blocker" class="mf-inline mf-quick"><input class="mf-quick" name="title" placeholder="记下本节的问题" aria-label="教材问题" required maxlength="4000"><button class="ghost-btn">记录问题</button></form></div><p class="tiny" id="pl-mf-status" role="status"></p>';box.querySelector('#pl-start-focus').onclick=()=>act(async()=>{await api.start({context:ctx});if(api.row.current.state==='Paused')await api.command('resume');box.querySelector('#pl-mf-status').textContent='已开始；可以留在教材页继续阅读。';},{redraw:false});box.querySelector('form').onsubmit=e=>{e.preventDefault();const form=e.target;act(async()=>{await addBlocker(new FormData(form).get('title'),ctx);form.reset();box.querySelector('#pl-mf-status').textContent='问题已保存到心流。';},{redraw:false});};}
export function isFocusing(){return api?.row.current?.state==='Focusing';}
export function current(){return api?.row.current;}

export async function pauseForReview(){if(api?.row.current?.state==='Focusing')await api.command('suspend');}
